const mix=document.getElementById('mix'),panel=document.createElement('div');panel.id='footsteps';panel.className='panel';
panel.innerHTML=`<div class="eyebrow">FOOTSTEP-FIRST · V-389 · NO PAID GENERATION</div><h2>Soft steps · contact micro-proof</h2><p>Real Rig_Medium, native Walking_A / Running_A. Foot contacts—not a metronome—drive soft, low-mid one-shots. Landing belongs to the synthetic support state. No World integration yet.</p><div class="foot-layout"><div id="footCanvas" style="max-width:640px;overflow:hidden"></div><div><p><button class="btn primary" id="footLoad">1 · Inspect motion source</button> <button class="btn" id="footAudio" disabled>2 · Enable existing audio</button></p><p><button class="btn" data-foot-mode="idle" disabled>Idle / stop steps</button> <button class="btn" data-foot-mode="walk" disabled>Walk · Walking_A</button> <button class="btn" data-foot-mode="run" disabled>Run · Running_A</button> <button class="btn" id="footJump" disabled>Jump / support landing</button></p><label>Material under each foot <select id="footSurface"><option value="grass">Grass · Kenney CC0</option><option value="concrete">Concrete · Chequered Ink</option><option value="gravel">Gravel · Chequered Ink</option><option value="seam">Seam · left/right foot query</option></select></label><p><button class="btn" id="footDemo" disabled>Run 24 s contact fixture</button> <button class="btn" id="footReset" disabled>Reset measurements</button></p><p><button class="btn" id="footRecord" disabled>Record audible clip</button> <button class="btn" id="footExport">Download measurements + cues</button></p><p id="footStatus" aria-live="polite">Source inspection first. No new AudioContext is created by this panel.</p><p id="footLast" class="tiny"></p><p id="footMetrics" class="tiny"></p></div></div><video id="footVideo" controls hidden style="width:min(640px,100%)"></video><a id="footClipDownload" hidden>Download audible motion clip</a><details><summary>Measured contacts, decode, drift and cue evidence</summary><pre id="footDiagnostics" style="max-height:420px;overflow:auto;white-space:pre-wrap"></pre></details><p class="tiny">Grass + landing: Kenney CC0. Concrete/gravel: Chequered Ink 400 Sounds Pack, incorporated-project use; not CC0. <a href="./footsteps/LICENCES.md">Source &amp; licence receipt</a>. Processed donor sounds, not clay recordings. Jog, sprint and dance contacts deferred. TTS ducking stays with the existing music mixer.</p>`;
mix.append(panel);const style=document.createElement('style');style.textContent='.foot-layout{display:flex;gap:20px;flex-wrap:wrap}.foot-layout>div{flex:1;min-width:280px}#footCanvas canvas{width:100%!important;height:auto!important;display:block}#footsteps select{max-width:100%}';document.head.append(style);
panel.insertAdjacentHTML('beforeend','<p class="tiny">Recorded browser proof: <a href="./footsteps/proof/footstep-v389.mp3">Hear the three banks + landing</a> · <a href="./footsteps/proof/footstep-v389.mp4">Watch the audible motion clip</a> · <a href="./footsteps/proof/browser-fixture.json">Exact recorded measurements</a>. Live controls above rerun the fixture; recording is not a sound-design acceptance.</p>');
// Lazy loading keeps all existing sections usable if the optional 3D CDN is unavailable.
let loaded=false;document.getElementById('footLoad').onclick=async()=>{if(loaded)return;loaded=true;try{await import('./preview.mjs');document.getElementById('footLoad').click();}catch(e){loaded=false;document.getElementById('footStatus').textContent=`Motion module unavailable: ${e.message}`;}};
if(location.hash==='#footsteps'){document.querySelector('[data-view="mix"]').click();panel.scrollIntoView();}
